/* C API of the Rust port of `lcm.c`, generated by rust-anything. */
#ifndef LCM_RS_H
#define LCM_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

unsigned long lcm(unsigned long a, unsigned long b);
unsigned long lcm_not_zero(unsigned long a, unsigned long b);

/* The same functions under `rust_anything_` names, for shadow runs. */
unsigned long rust_anything_lcm(unsigned long a, unsigned long b);
unsigned long rust_anything_lcm_not_zero(unsigned long a, unsigned long b);

#endif /* LCM_RS_H */
